70	type AxisInnerStoreCacheProp = 'axisTick' | 'axisLabel';
71	type AxisInnerStore = {
72	    axisTick: AxisCache<AxisCategoryTickLabelCacheKey<'axisTick'>, AxisCategoryTickCreated>
73	    axisLabel: AxisCache<AxisCategoryTickLabelCacheKey<'axisLabel'>, AxisCategoryLabelCreated>
