101	export function createAxisLabelsComputingContext(kind: AxisTickLabelComputingKind): AxisLabelsComputingContext {
102	    return {
103	        out: {
104	            noPxChangeTryDetermine: []
105	        },
106	        kind,
107	    };
108	}
